const localTicketMutationBarrier=createRefreshBarrier();
function beginLocalTicketCreation(){
  const release=localTicketMutationBarrier.begin();
  return async()=>{
    await new Promise<void>(next=>requestAnimationFrame(()=>{next()}));
    await waitForTicketMotionSettled();
    release();
  };
}
async function refreshAfterOpenSelectsClose(task:()=>Promise<void>){
  if(selectSafeProjectRefresh)return selectSafeProjectRefresh;
  backgroundProjectRefresh=true;
  if(!openSelect()){try{await task()}finally{backgroundProjectRefresh=false}return}
  const waitForClose=async()=>{for(let open=openSelect();open;open=openSelect())await new Promise<void>(resolve=>{open.addEventListener('wa-after-hide',()=>{resolve()},{once:true})})};
  selectSafeProjectRefresh=waitForClose().then(task).finally(()=>{selectSafeProjectRefresh=undefined;backgroundProjectRefresh=false});
  return selectSafeProjectRefresh;
}
function scheduleRepositoryRefresh(current:Project){const existing=repositoryRefreshTimers.get(current.id);if(existing!==undefined)window.clearTimeout(existing);repositoryRefreshTimers.set(current.id,window.setTimeout(()=>{repositoryRefreshTimers.delete(current.id);if(project()?.id===current.id)void refreshRepositoryStatus()},180))}
