  if(typeof patch.title==='string'&&titleEditing.value)titleDraftBase=patch.title;
  if(Object.hasOwn(patch,'blocked_reason')&&blockedReasonEditing.value)blockedReasonDraftBase=typeof patch.blocked_reason==='string'?patch.blocked_reason:'';
  if(Object.hasOwn(patch,'blocked_reason')&&readerBlockedReasonEditing.value)readerBlockedReasonDraftBase=typeof patch.blocked_reason==='string'?patch.blocked_reason:'';
