async function submitNewTicket(){const origin=project(),provider=defaultProvider(),title=composerTitle.value.trim();if(!origin||!title||composerScreening.value||composerSubmitting.value||!(provider?.capabilities.create??true))return;const client=new Api(origin.apiPath),files=composerAttachments.value.map(item=>item.file),batch_id=crypto.randomUUID(),placement=newTicketCreationPlacement(selectedView.value,composerUpNext.value),finishLocalCreation=beginLocalTicketCreation();composerSubmitting.value=true;composerAttachmentMessage.value=files.length?`Creating ticket and adding ${files.length} attachment${files.length===1?'':'s'}…`:'Creating ticket…';composerAttachmentError.value=false;try{const result=await createTicketWithAttachments(files,()=>client.createCheckoutTicket(origin.id,{title,details:composerDetails.value,category:composerCategory.value,...placement}),async(created,file)=>uploadAttachmentWithPoster(client,origin,created,file,{batch_id,actor:{role:'human'}}),created=>{resetTicketComposer();if(project()?.id!==origin.id)return;cancelTicketDrafts();tickets.value=[created,...tickets.value.filter(ticket=>ticket.id!==created.id)];selectedTicket.value=null;selectedTicketSlugs.value=[created.slug];ticketSelectionAnchor=created.slug;presentTicket(created);beginDetailsEdit();window.setTimeout(()=>activeTicketSurface().querySelector<HTMLElement>('[name="markdown-source"]')?.focus(),300)});const failure=describeNewTicketAttachmentFailures(result.failed);if(project()?.id!==origin.id)return;if(selectedTicket.value?.id===result.ticket.id)selectedTicket.value={...selectedTicket.value,attachments:result.ticket.attachments};if(failure){inspectorTab.value='attachments';attachmentMessage.value=failure;error.value=failure}}catch(reason){const message=reason instanceof Error?reason.message:String(reason);composerAttachmentMessage.value=`Ticket creation failed: ${message}`;composerAttachmentError.value=true;composerSubmitting.value=false}finally{await finishLocalCreation()}}
