document.addEventListener('pointermove',event=>{const gesture=attachmentAnnotationGesture;if(!gesture||event.pointerId!==gesture.pointerId)return;event.preventDefault();const dx=(event.clientX-gesture.startX)*10_000/gesture.surface.width,dy=(event.clientY-gesture.startY)*10_000/gesture.surface.height,base=gesture.annotation;let next={...base};if(gesture.kind==='draw'){const point=annotationPoint(event,gesture.surface);next={...base,x:Math.min(base.x,point.x),y:Math.min(base.y,point.y),width:Math.max(1,Math.abs(point.x-base.x)),height:Math.max(1,Math.abs(point.y-base.y))}}else if(gesture.kind==='move'){next={...base,x:clampAnnotation(Math.min(10_000-base.width,base.x+dx)),y:clampAnnotation(Math.min(10_000-base.height,base.y+dy))}}else{const handle=gesture.handle??'',right=base.x+base.width,bottom=base.y+base.height;if(handle.includes('w')){next.x=clampAnnotation(Math.min(right-50,base.x+dx));next.width=right-next.x}if(handle.includes('e'))next.width=clampAnnotation(Math.max(50,Math.min(10_000-base.x,base.width+dx)));if(handle.includes('n')){next.y=clampAnnotation(Math.min(bottom-50,base.y+dy));next.height=bottom-next.y}if(handle.includes('s'))next.height=clampAnnotation(Math.max(50,Math.min(10_000-base.y,base.height+dy)))}attachmentGalleryAnnotations.value=attachmentGalleryAnnotations.value.map(item=>item.id===base.id?next:item)});
document.addEventListener('pointermove',event=>{const gesture=attachmentRangeGesture;if(!gesture||event.pointerId!==gesture.pointerId)return;event.preventDefault();setGalleryAnnotationEndpoint(gesture.annotationId,gesture.endpoint,(event.clientX-gesture.track.left)*attachmentGalleryDuration.value/gesture.track.width)});
